mapper.select:
/* file : MakeMetaSimulationSchedulerMapper.xml, id : getJobList */
SELECT *, (SELECT USER_ID FROM TB_USER A WHERE U.REG_USER_SEQ = A.USER_SEQ LIMIT 1) USER_ID
FROM TB_META_AUGMENT U
WHERE U.AUGMENT_TP = #{augment_tp}
  AND U.AUGMENT_STATUS = #{augment_status}
  AND U.CYCLE_TP = #{cycle_tp}
  AND U.DEL_YN = 'N'
  AND U.USE_YN = 'Y'
ORDER BY MDFCN_DT ASC, U.MODEL_SEQ ASC
LIMIT #{limitCnt}

mapper.insert:
/* file : FilesMapper.xml, id : saveAugmentLog */
INSERT
INTO TB_META_AUGMENT_LOG ( AUGMENT_LOG_SEQ
                         , AUGMENT_SEQ
                         , MODEL_SEQ
                         , FILE_SEQ
                         , AUGMENT_STATUS
                         , ERR_TP
                         , ERR_CD
                         , ERR_NM
                         , ERR_CN
                         , DATA_CRT_LAST_HR)
VALUES ( #{augment_log_seq}
       , #{augment_seq}
       , #{model_seq}
       , #{file_seq}
       , #{augment_status}
       , #{err_tp}
       , #{err_cd}
       , #{err_nm}
       , #{err_cn}
       , #{data_crt_last_hr})

mapper.update:
UPDATE TB_META_AUGMENT
SET DATA_CRT_LAST_HR = #{data_crt_last_hr}
WHERE AUGMENT_SEQ = #{augment_seq}

UPDATE TB_META_AUGMENT
SET DATA_CRT_LAST_HR = #{dataCrtLastHr},
    AUGMENT_STATUS   = #{augmentStatus}
WHERE AUGMENT_SEQ = #{augmentSeq};

UPDATE TB_META_AUGMENT
SET AUGMENT_STATUS = #{augmentStatus}
WHERE AUGMENT_SEQ = #{augmentSeq};
